1	package config
2	
3	import (
4		"bytes"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9	
10		"gopkg.in/yaml.v3"
11	)
12	
13	// Path returns the resolved config file path.
14	// Resolution order: WIRE_CONFIG env var → XDG_CONFIG_HOME/wire/config.yaml →
15	// ~/.config/wire/config.yaml.
16	func Path() string {
17		if v := os.Getenv("WIRE_CONFIG"); v != "" {
18			return v
19		}
20		base := os.Getenv("XDG_CONFIG_HOME")
21		if base == "" {
22			home, _ := os.UserHomeDir()
23			base = filepath.Join(home, ".config")
24		}
25		return filepath.Join(base, "wire", "config.yaml")
26	}
27	
28	// WriteFile marshals cfg to YAML and atomically replaces the config file.
29	func WriteFile(cfg *Config) error {
30		path := Path()
31		data, err := yaml.Marshal(cfg)
32		if err != nil {
33			return fmt.Errorf("marshaling config: %w", err)
34		}
35		tmp := path + ".tmp"
36		if err := os.WriteFile(tmp, data, 0644); err != nil {
37			return fmt.Errorf("writing config temp file: %w", err)
38		}
39		if err := os.Rename(tmp, path); err != nil {
40			os.Remove(tmp)
41			return fmt.Errorf("renaming config file: %w", err)
42		}
43		return nil
44	}
45	
46	type Config struct {
47		Listen   string             `yaml:"listen"`
48		Backends map[string]Backend `yaml:"backends"`
49		Peers    []string           `yaml:"peers"`
50		Monitor  bool               `yaml:"monitor"`
51	}
52	
53	type Backend struct {
54		// Managed backend (llama-server)
55		Model     string   `yaml:"model"`      // HuggingFace ref, e.g. "Qwen/Qwen3-Coder-30B-A3B-Instruct-GGUF:Q4_K_M"
56		Context   int      `yaml:"context"`    // Context window size
57		GPULayers int      `yaml:"gpu_layers"` // -ngl flag
58		Slots     int      `yaml:"slots"`      // Number of parallel slots (--parallel). Default: 1.
59		Pooling   string   `yaml:"pooling"`    // "mean", "cls", "rank" — triggers --embedding flag
60		Extra     []string `yaml:"extra"`      // Additional llama-server flags
61	
62		// External backend (Ollama, OpenAI, Anthropic, etc.)
63		URL      string `yaml:"url"`      // If set, backend is external — no process management
64		APIKey   string `yaml:"api_key"`  // Bearer token or x-api-key
65		Provider string `yaml:"provider"` // "openai" (default) or "anthropic"
66	}
67	
68	// IsManaged reports whether wire manages the llama-server process for this backend.
69	func (b Backend) IsManaged() bool { return b.URL == "" }
70	
71	// IsExternal reports whether this backend is an external service.
72	func (b Backend) IsExternal() bool { return !b.IsManaged() }
73	
74	// ValidationError describes a config validation failure.
75	type ValidationError struct {
76		Field   string
77		Message string
78	}
79	
80	func (e *ValidationError) Error() string {
81		return fmt.Sprintf("config validation: %s: %s", e.Field, e.Message)
82	}
83	
84	// Load reads the config from disk, applies defaults, and validates it.
85	// Path resolution order: WIRE_CONFIG env var → XDG_CONFIG_HOME/wire/config.yaml →
86	// ~/.config/wire/config.yaml.
87	func Load() (*Config, error) {
88		path := Path()
89	
90		data, err := os.ReadFile(path)
91		if err != nil {
92			if errors.Is(err, os.ErrNotExist) {
93				return nil, fmt.Errorf("config file not found at %s: %w", path, err)
94			}
95			return nil, fmt.Errorf("reading config %s: %w", path, err)
96		}
97	
98		cfg := new(Config)
99		dec := yaml.NewDecoder(bytes.NewReader(data))
100		dec.KnownFields(true)
101		if err := dec.Decode(cfg); err != nil {
102			return nil, fmt.Errorf("parsing config %s: %w", path, err)
103		}
104	
105		applyDefaults(cfg)
106	
107		if err := validate(cfg); err != nil {
108			return nil, err
109		}
110	
111		return cfg, nil
112	}
113	
114	func applyDefaults(cfg *Config) {
115		if cfg.Listen == "" {
116			cfg.Listen = ":8080"
117		}
118		for name, b := range cfg.Backends {
119			if b.Provider == "" {
120				b.Provider = "openai"
121			}
122			if b.Slots == 0 {
123				b.Slots = 1
124			}
125			cfg.Backends[name] = b
126		}
127	}
128	
129	func validate(cfg *Config) error {
130		for name, b := range cfg.Backends {
131			switch {
132			case b.Model != "" && b.URL != "":
133				return &ValidationError{
134					Field:   "backends." + name,
135					Message: "cannot set both model and url",
136				}
137			case b.Model == "" && b.URL == "":
138				return &ValidationError{
139					Field:   "backends." + name,
140					Message: "must set either model or url",
141				}
142			}
143		}
144		return nil
145	}
