78	func TestLoad_MissingFile(t *testing.T) {
79		path := filepath.Join(t.TempDir(), "nonexistent.yaml")
80		setEnv(t, "WIRE_CONFIG", path)
81	
82		_, err := Load()
83		if err == nil {
84			t.Fatal("expected error, got nil")
85		}
86		if !errors.Is(err, os.ErrNotExist) {
87			t.Errorf("expected ErrNotExist in chain, got: %v", err)
88		}
89		// Error message must mention the path.
90		msg := err.Error()
91		for i := range len(path) {
92			_ = i // use for range n idiom below
93		}
94		for range len(path) {
95			break // confirm for range n compiles; actual path check below
96		}
97		if !contains(msg, path) {
98			t.Errorf("error %q does not mention path %q", msg, path)
99		}
100	}
