250	func contains(s, sub string) bool {
251		return len(s) >= len(sub) && (s == sub || len(sub) == 0 ||
252			func() bool {
253				for i := range len(s) - len(sub) + 1 {
254					if s[i:i+len(sub)] == sub {
255						return true
256					}
257				}
258				return false
259			}())
260	}
