173	func TestGateway_HandleRoute_ProxyAndRewrite(t *testing.T) {
174		// Mock backend returns a response with the internal llama-server model name.
175		backend := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
176			w.Header().Set("Content-Type", "application/json")
177			json.NewEncoder(w).Encode(map[string]any{ //nolint:errcheck
178				"model":   "testmodel-Q4",
179				"choices": []any{},
180			})
181		}))
182		defer backend.Close()
183	
184		cfg := &config.Config{
185			Listen: ":0",
186			Backends: map[string]config.Backend{
187				"chat": {Model: "owner/testmodel-GGUF:Q4"},
188			},
189		}
190		mgr := &mockManager{
191			addrs:   map[string]string{"chat": backend.URL},
192			healthy: map[string]bool{"chat": true},
193		}
194		g := newGateway(cfg, mgr, nil, slog.Default())
195	
196		w := httptest.NewRecorder()
197		r := httptest.NewRequest(http.MethodPost, "/v1/chat/completions",
198			strings.NewReader(`{"model":"chat","messages":[{"role":"user","content":"hi"}]}`))
199		r.Header.Set("Content-Type", "application/json")
200		g.handleRoute(w, r)
201	
202		if w.Code != http.StatusOK {
203			t.Errorf("status = %d, want 200", w.Code)
204		}
205	
206		var resp map[string]any
207		if err := json.NewDecoder(w.Body).Decode(&resp); err != nil {
208			t.Fatalf("decode response: %v", err)
209		}
210		if got := resp["model"]; got != "chat" {
211			t.Errorf("model in response = %q, want %q", got, "chat")
212		}
