215	func TestGateway_HandleRoute_BodyPreserved(t *testing.T) {
216		// Verify the full request body reaches the backend unchanged.
217		var receivedBody []byte
218		backend := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
219			receivedBody, _ = io.ReadAll(r.Body)
220			w.Header().Set("Content-Type", "application/json")
221			w.Write([]byte(`{"model":"m","choices":[]}`)) //nolint:errcheck
222		}))
223		defer backend.Close()
224	
225		cfg := &config.Config{
226			Listen: ":0",
227			Backends: map[string]config.Backend{
228				"m": {URL: backend.URL},
229			},
230		}
231		mgr := &mockManager{
232			addrs:   map[string]string{"m": backend.URL},
