38	// resolve returns the backend name for the given model string.
39	func (rt *routeTable) resolve(model string) (string, error) {
40		if name, ok := rt.aliases[model]; ok {
41			return name, nil
42		}
43		return "", fmt.Errorf("unknown model %q", model)
44	}
