26	
27	const usageText = `Usage: wire <command> [arguments]
28	
29	Commands:
30	  start               Start the gateway (foreground)
31	  stop                Stop the running gateway
32	  status              Show backend status
33	  swap <backend> <model>  Hot-swap a backend's model
34	  build               Build and install llama-server from source (ROCm)
35	  remove              Remove a previous llama-server installation
36	  version             Print version and exit
37	
38	Environment:
39	  WIRE_CONFIG         Config file path (default: ~/.config/wire/config.yaml)
40	  WIRE_LLAMA_SRC      llama.cpp source directory (default: ~/Development/llama.cpp)
41	  WIRE_GPU_TARGET     AMD GPU target (default: gfx1151; find yours: rocminfo | grep gfx)
42	  WIRE_PREFIX         Install prefix (default: ~/.local)
43	`
44	
45	// Run dispatches CLI commands from the given argument slice (os.Args[1:]).
46	// It returns an exit code suitable for os.Exit.
47	func Run(args []string) int {
48		if err := dispatch(args); err != nil {
49			fmt.Fprintln(os.Stderr, "wire:", err)
50			return 1
51		}
52		return 0
53	}
54	
55	func dispatch(args []string) error {
56		if len(args) == 0 {
57			fmt.Print(usageText)
58			return nil
59		}
60		switch args[0] {
61		case "help", "--help", "-h":
62			fmt.Print(usageText)
63			return nil
64		case "start":
65			return runStart()
66		case "stop":
67			return runStop()
68		case "status":
69			return runStatus()
70		case "swap":
71			if len(args) < 3 {
72				return fmt.Errorf("swap requires <backend> and <model>\nUsage: wire swap <backend> <model>")
73			}
74			return runSwap(args[1], args[2])
75		case "version", "--version", "-v":
76			fmt.Printf("wire %s (%s) built %s\n", internal.Version, internal.Commit, internal.BuildDate)
77			return nil
78		case "build":
79			return runBuild(args[1:])
80		case "remove":
81			return runRemove(args[1:])
82		default:
83			fmt.Print(usageText)
84			return fmt.Errorf("unknown command: %q", args[0])
85		}
86	}
87	
88	// listenURL converts the listen address from config to an http:// URL.
89	func listenURL(listen string) string {
90		if strings.HasPrefix(listen, ":") {
91			return "http://localhost" + listen
92		}
93		return "http://" + listen
94	}
95	
96	func runStart() error {
97		cfg, err := config.Load()
98		if err != nil {
99			return fmt.Errorf("loading config: %w", err)
100		}
101	
102		pidPath := pidfile.Path()
103		if err := pidfile.Write(pidPath); err != nil {
104			return err
105		}
106		defer os.Remove(pidPath)
107	
108		// bgCtx drives the process manager; cancelled only after gateway drains.
109		bgCtx, bgCancel := context.WithCancel(context.Background())
110		defer bgCancel()
111	
112		// shutCtx is cancelled by SIGTERM/SIGINT. Its Cause is the received signal.
113		shutCtx, stop := signal.NotifyContext(bgCtx, syscall.SIGTERM, syscall.SIGINT)
114		defer stop()
115	
116		// sighupCh receives SIGHUP for config reload.
117		sighupCh := make(chan os.Signal, 1)
118		signal.Notify(sighupCh, syscall.SIGHUP)
119		defer signal.Stop(sighupCh)
120	
121		mgr := process.New(cfg, slog.Default())
122		if err := mgr.Start(bgCtx); err != nil {
123			return fmt.Errorf("starting process manager: %w", err)
124		}
125	
126		var hub *monitor.Hub
127		if cfg.Monitor {
128			hub = monitor.NewHub(slog.Default(), mgr.Events(), mgr.Snapshot)
129			hub.Start()
130			defer hub.Stop()
131		}
132	
133		gw := gateway.New(cfg, mgr, hub, slog.Default())
134		gwErrCh := make(chan error, 1)
135		go func() { gwErrCh <- gw.ListenAndServe(shutCtx) }()
136	
137		slog.Info("wire ready", "listen", cfg.Listen, "version", internal.Version, "commit", internal.Commit)
138	
139		// swapMu serialises SIGHUP handling so overlapping reloads are dropped.
140		var swapMu sync.Mutex
141	
142		for {
143			select {
144			case err := <-gwErrCh:
145				bgCancel()
146				_ = mgr.Stop()
147				if err != nil {
148					return fmt.Errorf("gateway error: %w", err)
149				}
150				return nil
151	
152			case <-shutCtx.Done():
153				if cause := context.Cause(shutCtx); cause != nil {
154					slog.Info("shutting down", "cause", cause)
155				}
156				stop() // release signal resources early
157				// Wait for gateway to drain connections, then stop process manager.
158				if err := <-gwErrCh; err != nil {
159					slog.Error("gateway shutdown error", "error", err)
160				}
161				bgCancel()
162				return mgr.Stop()
163	
164			case <-sighupCh:
165				if !swapMu.TryLock() {
166					slog.Warn("SIGHUP received while swap in progress, ignoring")
167					continue
168				}
169				go func() {
170					defer swapMu.Unlock()
171					newCfg, loadErr := config.Load()
172					if loadErr != nil {
173						slog.Error("failed to reload config on SIGHUP", "error", loadErr)
174						return
175					}
176					for name, b := range newCfg.Backends {
177						oldB, ok := cfg.Backends[name]
178						if !ok || !b.IsManaged() {
179							continue
180						}
181						if b.Model != oldB.Model {
182							slog.Info("swapping backend model", "backend", name, "old", oldB.Model, "new", b.Model)
183							if swapErr := mgr.Swap(bgCtx, name, b.Model); swapErr != nil {
184								slog.Error("model swap failed", "backend", name, "error", swapErr)
185							}
186						}
187					}
188					cfg = newCfg
189				}()
190			}
191		}
192	}
193	
194	func runStop() error {
195		pidPath := pidfile.Path()
196		pid, err := pidfile.Read(pidPath)
197		if err != nil {
198			return err
199		}
200		proc, err := os.FindProcess(pid)
201		if err != nil {
202			return fmt.Errorf("finding process %d: %w", pid, err)
203		}
204		if err := proc.Signal(syscall.SIGTERM); err != nil {
205			return fmt.Errorf("sending SIGTERM to pid %d: %w", pid, err)
206		}
207	
208		// Poll /proc/<pid> via kill -0 for up to 10 seconds.
209		deadline := time.Now().Add(10 * time.Second)
210		for time.Now().Before(deadline) {
211			if err := proc.Signal(syscall.Signal(0)); err != nil {
212				fmt.Printf("wire stopped (pid %d)\n", pid)
213				return nil
214			}
215			time.Sleep(200 * time.Millisecond)
216		}
217	
218		// Still alive: force kill.
219		_ = proc.Signal(syscall.SIGKILL)
220		fmt.Printf("wire force-killed (pid %d)\n", pid)
221		return nil
222	}
223	
224	func runStatus() error {
225		cfg, err := config.Load()
