27		for name, b := range backends {
28			slots := b.Slots
29			if slots <= 0 {
30				slots = 1
31			}
32			at.backends[name] = &backendSlots{
33				slotCount:   slots,
34				assignments: make(map[uint64]int),
35			}
36		}
37		return at
38	}
39	
40	// Assign returns the slot ID to use for a request with the given prefix hash on
41	// the named backend. Returns (-1, false) when hash is 0 or the backend is unknown.
42	func (at *affinityTable) Assign(backend string, hash uint64) (int, bool) {
43		if hash == 0 {
44			return -1, false
45		}
46	
47		at.mu.Lock()
48		defer at.mu.Unlock()
49	
50		bs, ok := at.backends[backend]
51		if !ok {
52			return -1, false
53		}
54	
55		// Single-slot backends always use slot 0; no table needed.
56		if bs.slotCount == 1 {
57			return 0, true
58		}
59	
60		// Existing assignment: refresh LRU position.
61		if slotID, exists := bs.assignments[hash]; exists {
62			for i, h := range bs.lru {
63				if h == hash {
64					bs.lru = append(bs.lru[:i], bs.lru[i+1:]...)
65					break
66				}
67			}
68			bs.lru = append(bs.lru, hash)
69			return slotID, true
70		}
71	
72		// Free slot available: assign the next unused slot ID.
73		if len(bs.assignments) < bs.slotCount {
74			used := make(map[int]bool, len(bs.assignments))
75			for _, s := range bs.assignments {
76				used[s] = true
77			}
78			for i := range bs.slotCount {
79				if !used[i] {
80					bs.assignments[hash] = i
81					bs.lru = append(bs.lru, hash)
82					return i, true
83				}
84			}
85		}
86	
87		// All slots assigned: evict the oldest LRU entry and reuse its slot.
88		oldest := bs.lru[0]
89		slotID := bs.assignments[oldest]
90		bs.lru = bs.lru[1:]
91		delete(bs.assignments, oldest)
92		bs.assignments[hash] = slotID
93		bs.lru = append(bs.lru, hash)
94		return slotID, true
95	}
96	
97	// prefixHash returns a 64-bit FNV-1a hash of the dominant stable prefix in the
98	// request: the system message content, falling back to the first user message.
99	// Returns 0 on parse error or when no usable prefix is found.
100	func prefixHash(body []byte) uint64 {
101		var payload struct {
102			Messages []struct {
103				Role    string `json:"role"`
104				Content string `json:"content"`
105			} `json:"messages"`
106		}
107		if err := json.Unmarshal(body, &payload); err != nil {
108			return 0
109		}
110	
111		var text string
112		for _, m := range payload.Messages {
113			if m.Role == "system" {
114				text = m.Content
115				break
116			}
117		}
118		if text == "" {
119			for _, m := range payload.Messages {
120				if m.Role == "user" {
121					text = m.Content
122					break
123				}
124			}
125		}
126		if text == "" {
127			return 0
128		}
129	
130		h := fnv.New64a()
131		h.Write([]byte(text)) //nolint:errcheck
132		return h.Sum64()
133	}
134	
135	// injectSlot inserts `"id_slot":N,` immediately after the opening brace of a
136	// JSON object body. The body must be a valid JSON object (guaranteed by the
137	// model extraction that precedes this call).
138	func injectSlot(body []byte, slotID int) []byte {
139		for i, b := range body {
140			if b == '{' {
141				field := `"id_slot":` + strconv.Itoa(slotID) + `,`
142				result := make([]byte, 0, len(body)+len(field))
143				result = append(result, body[:i+1]...)
144				result = append(result, field...)
145				result = append(result, body[i+1:]...)
146				return result
147			}
148		}
149		return body
150	}
