	if !local.IsManaged() {
		t.Error("local backend should be managed")
	}
	if local.IsExternal() {
		t.Error("local backend should not be external")
	}
	if local.Model != "Qwen/Qwen3-Coder-30B-A3B-Instruct-GGUF:Q4_K_M" {
