func TestIntegration_Fallback_NoSlotOnHashZero(t *testing.T) {
	var (
		mu       sync.Mutex
		received []byte
	)

	backend := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		mu.Lock()
