	// Empty messages → hash=0 → no id_slot injected.
	reqBody := `{"model":"test","messages":[]}`
	resp, err := http.Post(gwServer.URL+"/v1/chat/completions", "application/json", strings.NewReader(reqBody))
	if err != nil {
		t.Fatalf("request failed: %v", err)
	}
